 import unittest
from candidate import get_positive

class TestGetPositive(unittest.TestCase):
    def test_get_positive_normalcase(self):
        self.assertEqual(get_positive([-1, 2, -4, 5, 6]), [2, 5, 6])

    def test_get_positive_empty_list(self):
        self.assertEqual(get_positive([]), [])

    def test_get_positive_none_value(self):
        self.assertEqual(get_positive(None), [])

    def test_get_positive_negative_numbers(self):
        self.assertEqual(get_positive([-5, -3, -2]), [])

    def test_get_positive_zero(self):
        self.assertEqual(get_positive([0]), [])

    def test_get_positive_mixed_numbers(self):
        self.assertEqual(get_positive([-3, 4, -6, 8]), [4, 8])

    def test_get_positive_floats(self):
        self.assertEqual(get_positive([-3.5, 4.2, -6.7, 8.9]), [4.2, 8.9])

if __name__ == '__main__':
    unittest.main()
